# Exchanges for clusters 3–11. Claims are phrased so that affirming them is the side the cluster's "For" stance takes
# (in cluster 11, the risk claim), so colours mean the same thing as everywhere else.
def M(key, side, type, id=None, gist="", to="claim", label=None):
    d = dict(key=key, side=side, type=type, gist=gist, to=to)
    if id: d["id"] = id
    if label: d["label"] = label
    return d
def P(id, why): return dict(id=id, why=why)

